mapper.update:
UPDATE sim_user SET email = #{email}, email_verified_at = NULL,
    revision = revision + 1, security_version = security_version + 1, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{id} AND revision = #{revision}

UPDATE sim_user SET status = #{status}, revision = revision + 1,
    security_version = security_version + 1, updated_at = UTC_TIMESTAMP(3)
WHERE id = #{id} AND revision = #{revision}

UPDATE sim_user u JOIN sim_user_role ur ON ur.user_id = u.id
SET u.security_version = u.security_version + 1, u.revision = u.revision + 1,
    u.updated_at = UTC_TIMESTAMP(3) WHERE ur.role_id = #{roleId}
